steps.script:
# Mid-drag, button still down: the model must ALREADY be held at its 3" cap
# (16" of cursor travel), not out at the cursor waiting to snap back.
var m = tree.root.get_node("Main")
var fc = m.fight_controller
var key = fc.drag_model_id
if key == "":
	return false
var orig = fc.original_model_positions.get(key, Vector2.ZERO)
var live = fc.current_model_positions.get(key, Vector2.ZERO)
var live_in = Measurement.px_to_inches(orig.distance_to(live))
var cap = fc._effective_pile_in_cap_inches(key)
var cursor_in = Measurement.px_to_inches(orig.distance_to(Vector2(600.0, 600.0)))
m.set_meta("pile_in_key", key)
m.set_meta("pile_in_probe", "cursor=%.2f\" live=%.3f\" cap=%.2f\"" % [cursor_in, live_in, cap])
return cursor_in > 14.0 and abs(live_in - cap) <= 0.05

# The drop lands where the ghost was — no visible snap-back.
var m = tree.root.get_node("Main")
var fc = m.fight_controller
var key = str(m.get_meta("pile_in_key", ""))
if key == "" or not fc.original_model_positions.has(key):
	return false
var orig = fc.original_model_positions[key]
var final_in = Measurement.px_to_inches(orig.distance_to(fc.current_model_positions[key]))
m.set_meta("pile_in_drop_probe", "final=%.3f\"" % final_in)
return abs(final_in - 3.0) <= 0.05

# Unclamped: mid-drag the model is out at the cursor, far past its 3" — the
# old behaviour, where the release then yanked it back.
var m = tree.root.get_node("Main")
var fc = m.fight_controller
var key = fc.drag_model_id
if key == "":
	return false
var orig = fc.original_model_positions.get(key, Vector2.ZERO)
var live_in = Measurement.px_to_inches(orig.distance_to(fc.current_model_positions.get(key, Vector2.ZERO)))
m.set_meta("pile_in_key", key)
m.set_meta("pile_in_unclamped_probe", "live=%.2f\" cap=%.2f\"" % [live_in, fc._effective_pile_in_cap_inches(key)])
return live_in > 10.0

# Part C — the PAD is always clamped, setting or no setting. Preference OFF,
# pad made the active device: the gate must still be on and the clamp must still
# hold an over-range point at the 3" cap. Called directly rather than by
# injecting mouse motion, which would flip the active device back to KBM.
SettingsService.set_drag_clamp_to_max_range(false)
var m = tree.root.get_node("Main")
var fc = m.fight_controller
if not InputDeviceManager.is_pad_active() or not fc.drag_clamp_active():
	return false
var key = str(m.get_meta("pile_in_key", ""))
if key == "" or not fc.original_model_positions.has(key):
	return false
fc.drag_model_id = key
var orig = fc.original_model_positions[key]
var clamped = fc._clamp_pile_in_to_budget(orig + Vector2(400.0, 500.0))
var reach = Measurement.px_to_inches(orig.distance_to(clamped))
var cap = fc._effective_pile_in_cap_inches(key)
fc.drag_model_id = ""
m.set_meta("pile_in_pad_probe", "pad_active=%s setting=%s clamped_reach=%.3f\" cap=%.2f\"" % [str(InputDeviceManager.is_pad_active()), str(SettingsService.drag_clamp_to_max_range), reach, cap])
return abs(reach - cap) <= 0.05
